const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const hongKong = ee.Geometry.Point([114.1694, 22.3193]); // Hong Kong center
  const region = hongKong.buffer(20000); // 20km buffer around Hong Kong

  // Time periods
  const janPeriod = ['2020-01-01', '2020-01-20'];
  const febPeriod = ['2020-02-10', '2020-02-25'];

  // 2. Data Acquisition
  const janCollection = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
    .filterDate(janPeriod[0], janPeriod[1])
    .filterBounds(region)
    .select('tropospheric_NO2_column_number_density');

  const febCollection = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
    .filterDate(febPeriod[0], febPeriod[1])
    .filterBounds(region)
    .select('tropospheric_NO2_column_number_density');

  // Check collection sizes
  const janSize = janCollection.size().getInfo();
  const febSize = febCollection.size().getInfo();

  console.log(`Jan Images: ${janSize}, Feb Images: ${febSize}`);

  if (janSize === 0 || febSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Calculate mean NO2 for each period
  const janMean = janCollection.mean();
  const febMean = febCollection.mean();

  // Get pixel counts to validate data
  const janCount = janMean.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  }).get('tropospheric_NO2_column_number_density').getInfo();

  const febCount = febMean.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  }).get('tropospheric_NO2_column_number_density').getInfo();

  console.log(`Jan Pixels: ${janCount}, Feb Pixels: ${febCount}`);

  if (janCount === 0 || febCount === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // 4. Calculation - Get mean NO2 values
  const janNO2 = janMean.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  }).get('tropospheric_NO2_column_number_density').getInfo();

  const febNO2 = febMean.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  }).get('tropospheric_NO2_column_number_density').getInfo();

  console.log(`Jan NO2: ${janNO2?.toFixed(6)}, Feb NO2: ${febNO2?.toFixed(6)}`);

  // 5. Validation & Final Answer
  if (janNO2 === null || febNO2 === null || 
      isNaN(janNO2) || isNaN(febNO2) ||
      janNO2 < 0 || febNO2 < 0) { // NO2 should be positive
    console.log("<answer>C3</answer>");
    return;
  }

  const decrease = febNO2 < janNO2;
  console.log(`Decrease: ${decrease}, Change: ${((febNO2 - janNO2) / janNO2 * 100).toFixed(1)}%`);

  if (decrease) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
